description:
Build the two halves of a memory viewer like the one in a debugger: a hex dump of any bytes, and readers that turn bytes back into numbers.

```cpp
std::string hexDump(const void* data, std::size_t size, std::uint64_t baseAddress);
std::uint64_t readLittleEndian(const unsigned char* bytes, int count);
std::int32_t readInt32(const unsigned char* bytes);
```

**hexDump** shows `size` bytes starting at `data`, 16 per line. Each line is:

- the address of its first byte, `baseAddress` plus the offset, as 8 uppercase hex digits;
- two spaces;
- for each of the 16 positions: one extra space before position 8, then either the byte as 2 uppercase hex digits and a space, or 3 spaces when the data has run out;
- a space, then `|`, then the 16 bytes (or fewer on the last line) as characters, with any byte outside 32 to 126 shown as `.`, then `|`.

Every line ends with `\n`. Zero bytes give an empty string. For example 16 bytes of `Hello, pointers!` at `0x1000`:

```text
00001000  48 65 6C 6C 6F 2C 20 70  6F 69 6E 74 65 72 73 21  |Hello, pointers!|
```

Because it takes `const void*`, it can dump anything: `hexDump(&someStruct, sizeof(someStruct), 0)`. Inside, view the bytes through a `const unsigned char*`.

**readLittleEndian** combines `count` bytes (1 to 8), lowest first, into one number. **readInt32** reads 4 bytes as a signed 32-bit number, so `FF FF FF FF` is `-1`.

starter.solution.cpp:
#include <cstddef>
#include <cstdint>
#include <string>

std::string hexDump(const void* data, std::size_t size, std::uint64_t baseAddress) { return ""; }
std::uint64_t readLittleEndian(const unsigned char* bytes, int count) { return 0; }
std::int32_t readInt32(const unsigned char* bytes) { return 0; }

solution.solution.cpp:
#include <cstddef>
#include <cstdint>
#include <string>

static void appendHex(std::string& out, std::uint64_t value, int digits)
{
    static const char* const HEX{ "0123456789ABCDEF" };
    for (int i{ digits - 1 }; i >= 0; --i) out += HEX[(value >> (4 * i)) & 0xF];
}

std::string hexDump(const void* data, std::size_t size, std::uint64_t baseAddress)
{
    const unsigned char* bytes{ static_cast<const unsigned char*>(data) };
    std::string out;
    for (std::size_t line{ 0 }; line < size; line += 16)
    {
        const std::size_t count{ size - line < 16 ? size - line : 16 };
        appendHex(out, baseAddress + line, 8);
        out += "  ";
        for (std::size_t i{ 0 }; i < 16; ++i)
        {
            if (i == 8) out += ' ';
            if (i < count) { appendHex(out, bytes[line + i], 2); out += ' '; }
            else out += "   ";
        }
        out += " |";
        for (std::size_t i{ 0 }; i < count; ++i)
        {
            const unsigned char c{ bytes[line + i] };
            out += (c >= 32 && c <= 126) ? static_cast<char>(c) : '.';
        }
        out += "|\n";
    }
    return out;
}

std::uint64_t readLittleEndian(const unsigned char* bytes, int count)
{
    std::uint64_t value{ 0 };
    for (int i{ 0 }; i < count; ++i) value |= static_cast<std::uint64_t>(bytes[i]) << (8 * i);
    return value;
}

std::int32_t readInt32(const unsigned char* bytes)
{
    return static_cast<std::int32_t>(static_cast<std::uint32_t>(readLittleEndian(bytes, 4)));
}

unitTests:
TEST("one full line") {
    const char text[]{ "Hello, pointers!" };
    CHECK_EQ(hexDump(text, 16, 0x1000), std::string("00001000  48 65 6C 6C 6F 2C 20 70  6F 69 6E 74 65 72 73 21  |Hello, pointers!|\n"));
}
TEST("a short last line is padded") {
    const unsigned char bytes[]{ 0x41, 0x00, 0xFF };
    CHECK_EQ(hexDump(bytes, 3, 0x20), std::string("00000020  41 00 FF") + std::string(42, ' ') + "|A..|\n");
}
TEST("several lines and addresses") {
    unsigned char bytes[20];
    for (int i{ 0 }; i < 20; ++i) bytes[i] = static_cast<unsigned char>(0x30 + i);
    const std::string dump{ hexDump(bytes, 20, 0xFFF8) };
    CHECK_EQ(dump.substr(0, 8), std::string("0000FFF8"));
    const std::size_t second{ dump.find('\n') + 1 };
    CHECK_EQ(dump.substr(second, 8), std::string("00010008"));
    CHECK_EQ(dump.substr(second, 22), std::string("00010008  40 41 42 43 "));
    CHECK(dump.find("|0123456789:;<=>?|") != std::string::npos);
    CHECK(dump.find("|@ABC|\n") != std::string::npos);
    CHECK_EQ(hexDump(bytes, 0, 0), std::string(""));
}
TEST("any object, through const void*") {
    const std::uint32_t value{ 0x12345678 };
    const std::string dump{ hexDump(&value, sizeof(value), 0) };
    CHECK_EQ(dump.substr(0, 21), std::string("00000000  78 56 34 12"));
}
TEST("reading numbers back") {
    const unsigned char bytes[]{ 0x78, 0x56, 0x34, 0x12, 0xFF, 0xFF, 0xFF, 0xFF };
    CHECK_EQ(readLittleEndian(bytes, 4), 0x12345678ull);
    CHECK_EQ(readLittleEndian(bytes, 2), 0x5678ull);
    CHECK_EQ(readLittleEndian(bytes, 8), 0xFFFFFFFF12345678ull);
    CHECK_EQ(readInt32(bytes), 0x12345678);
    CHECK_EQ(readInt32(bytes + 4), -1);
    const unsigned char minusTwo[]{ 0xFE, 0xFF, 0xFF, 0xFF };
    CHECK_EQ(readInt32(minusTwo), -2);
}

